const input = $input.first().json;
const texts = input.texts || [];
return texts.map(text => ({ json: { tenant_id: input.tenant_id, conversation_id: input.conversation_id, text } }));

const response = $json;
const original = $("Expandir textos").item.json;
const part = response.candidates?.[0]?.content?.parts?.[0];
const inline = part?.inlineData;

if (!inline || !inline.data) {
  return { json: { tenant_id: original.tenant_id, conversation_id: original.conversation_id, text: original.text, audio_generated: false, error: response.error?.message || 'Gemini TTS nao retornou audio' } };
}

const mimeType = inline.mimeType || 'audio/L16;rate=24000';
const rateMatch = mimeType.match(/rate=(\d+)/);
const sampleRate = rateMatch ? parseInt(rateMatch[1], 10) : 24000;
const bitsPerSample = 16;
const numChannels = 1;

const pcmBuffer = Buffer.from(inline.data, 'base64');
const byteRate = sampleRate * numChannels * (bitsPerSample / 8);
const blockAlign = numChannels * (bitsPerSample / 8);
const dataSize = pcmBuffer.length;

const header = Buffer.alloc(44);
header.write('RIFF', 0);
header.writeUInt32LE(36 + dataSize, 4);
header.write('WAVE', 8);
header.write('fmt ', 12);
header.writeUInt32LE(16, 16);
header.writeUInt16LE(1, 20);
header.writeUInt16LE(numChannels, 22);
header.writeUInt32LE(sampleRate, 24);
header.writeUInt32LE(byteRate, 28);
header.writeUInt16LE(blockAlign, 32);
header.writeUInt16LE(bitsPerSample, 34);
header.write('data', 36);
header.writeUInt32LE(dataSize, 40);

const wavBuffer = Buffer.concat([header, pcmBuffer]);

return {
  json: { tenant_id: original.tenant_id, conversation_id: original.conversation_id, text: original.text, audio_generated: true },
  binary: { data: { data: wavBuffer.toString('base64'), mimeType: 'audio/wav', fileName: 'resposta.wav' } }
};
